SourceCode.Declaration:
/// <summary>
/// controller class for MET Customer MDF consolidation batch processing
/// </summary>
class METCustomerMDFConsolidationBatchController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Specifies if the batch task is retryable for exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// New method
/// </summary>
protected void new()
{
    super(classStr(METCustomerMDFConsolidationBatchService), methodStr(METCustomerMDFConsolidationBatchService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "@MET:MDFFreeTextInvoiceGeneration";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METCustomerMDFConsolidationBatchController controller = new METCustomerMDFConsolidationBatchController();
    controller.parmArgs(_args);
    controller.startOperation();
}
